// Writes lib/src/version.dart from the version in pubspec.yaml, so the
// compiled executable knows its own version. The release workflow runs this
// after bumping the version.
import 'dart:io';

import 'package:yaml/yaml.dart';

void main() {
  final pubspec = loadYaml(File('pubspec.yaml').readAsStringSync()) as Map;
  final version = pubspec['version'] as String;
  File('lib/src/version.dart').writeAsStringSync('''
// Generated by tool/generate_version.dart from pubspec.yaml; don't edit.

/// The version of turbodart.
const packageVersion = '$version';
''');
  stdout.writeln('lib/src/version.dart: $version');
}
